{
  "implementation": "def solve(case):
    required = ['word_token_indices', 'word_labels', 'token_count']
    for key in required:
        if key not in case:
            raise ValueError(f'Missing required field: {key}')
    wti = case['word_token_indices']
    wl = case['word_labels']
    tc = case['token_count']
    if len(wti) != len(wl):
        raise ValueError('Mismatch between word_token_indices and word_labels lengths')
    assigned = [None] * tc
    for i, indices in enumerate(wti):
        label = wl[i]
        for idx in indices:
            if not (0 <= idx < tc):
                raise ValueError(f'Token index {idx} out of range')
            if assigned[idx] is not None:
                raise ValueError(f'Token index {idx} overlaps')
            assigned[idx] = label
    for idx in range(tc):
        if assigned[idx] is None:
            raise ValueError(f'Token index {idx} uncovered')
    token_labels = assigned
    kept_indices = [i for i, lab in enumerate(token_labels) if lab == 1]
    return {'kept_indices': kept_indices, 'token_labels': token_labels}"
}
